(function() {
  var PANEL_ID = 'cs-analytics-panel';
  var BTN_ID = 'cs-analytics-btn';
  var isPanelVisible = false;

  var stats = {
    totalCards: 0,
    totalWords: 0,
    tagCounts: {},
    dailyActivity: {},
    averageWordsPerCard: 0,
    mostUsedTags: [],
    cardsCreatedToday: 0,
    lastUpdated: null
  };

  function countWords(text) {
    if (!text || typeof text !== 'string') return 0;
    var trimmed = text.trim();
    if (trimmed.length === 0) return 0;
    return trimmed.split(/\s+/).length;
  }

  function getToday() {
    return new Date().toISOString().split('T')[0];
  }

  function recalculateStats(allCards) {
    stats.totalCards = allCards ? allCards.length : 0;
    stats.totalWords = 0;
    stats.tagCounts = {};
    stats.dailyActivity = {};
    stats.cardsCreatedToday = 0;
    var today = getToday();
    if (allCards) {
      for (var i = 0; i < allCards.length; i++) {
        var card = allCards[i];
        var words = countWords(card.body);
        stats.totalWords += words;
        if (card.tags) {
          for (var t = 0; t < card.tags.length; t++) {
            var tag = card.tags[t];
            stats.tagCounts[tag] = (stats.tagCounts[tag] || 0) + 1;
          }
        }
        var createdDate = card.createdAt ? card.createdAt.split('T')[0] : today;
        stats.dailyActivity[createdDate] = (stats.dailyActivity[createdDate] || 0) + 1;
        if (createdDate === today) {
          stats.cardsCreatedToday++;
        }
      }
    }
    stats.averageWordsPerCard = stats.totalCards > 0 ? Math.round(stats.totalWords / stats.totalCards) : 0;
    var sortedTags = Object.keys(stats.tagCounts).sort(function(a, b) {
      return stats.tagCounts[b] - stats.tagCounts[a];
    });
    stats.mostUsedTags = sortedTags.slice(0, 5);
    stats.lastUpdated = new Date().toLocaleTimeString();
  }

  function renderPanel() {
    var panel = document.getElementById(PANEL_ID);
    if (!panel) return;
    var topTagsHtml = '';
    if (stats.mostUsedTags.length > 0) {
      for (var i = 0; i < stats.mostUsedTags.length; i++) {
        var tag = stats.mostUsedTags[i];
        var count = stats.tagCounts[tag];
        var barWidth = Math.min(100, Math.round((count / stats.totalCards) * 100));
        topTagsHtml += '<div style="margin-bottom:6px;"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:2px;"><span style="color:#555;">' + tag + '</span><span style="color:#999;">' + count + '</span></div><div style="height:4px;background:#f0f0f0;border-radius:2px;"><div style="height:100%;width:' + barWidth + '%;background:#4a90d9;border-radius:2px;"></div></div></div>';
      }
    } else {
      topTagsHtml = '<div style="font-size:12px;color:#999;">No tags found</div>';
    }
    var contentHtml = '<div style="padding:16px;"><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;"><div style="background:#f8f9fa;padding:12px;border-radius:8px;text-align:center;"><div style="font-size:24px;font-weight:700;color:#333;">' + stats.totalCards + '</div><div style="font-size:11px;color:#888;margin-top:2px;">Total Cards</div></div><div style="background:#f8f9fa;padding:12px;border-radius:8px;text-align:center;"><div style="font-size:24px;font-weight:700;color:#333;">' + stats.cardsCreatedToday + '</div><div style="font-size:11px;color:#888;margin-top:2px;">Created Today</div></div><div style="background:#f8f9fa;padding:12px;border-radius:8px;text-align:center;"><div style="font-size:24px;font-weight:700;color:#333;">' + stats.totalWords + '</div><div style="font-size:11px;color:#888;margin-top:2px;">Total Words</div></div><div style="background:#f8f9fa;padding:12px;border-radius:8px;text-align:center;"><div style="font-size:24px;font-weight:700;color:#333;">' + stats.averageWordsPerCard + '</div><div style="font-size:11px;color:#888;margin-top:2px;">Avg Words/Card</div></div></div><div><div style="font-size:12px;font-weight:600;color:#555;margin-bottom:8px;">Top Tags</div>' + topTagsHtml + '</div><div style="margin-top:12px;font-size:10px;color:#bbb;text-align:right;">Updated: ' + (stats.lastUpdated || 'never') + '</div></div>';
    panel.querySelector('.cs-analytics-content').innerHTML = contentHtml;
  }

  function createUI() {
    if (document.getElementById(PANEL_ID)) return;
    var panel = document.createElement('div');
    panel.id = PANEL_ID;
    panel.style.cssText = 'position:fixed;top:60px;right:20px;width:300px;background:#fff;border:1px solid #ddd;border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,0.1);z-index:9999;font-family:system-ui,-apple-system,sans-serif;display:none;overflow:hidden;';
    panel.innerHTML = '<div style="padding:10px 14px;border-bottom:1px solid #eee;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:14px;font-weight:600;color:#333;">Analytics</span><button id="cs-analytics-close" style="background:none;border:none;font-size:18px;color:#999;cursor:pointer;">&times;</button></div><div class="cs-analytics-content"></div>';
    document.body.appendChild(panel);
    document.getElementById('cs-analytics-close').addEventListener('click', togglePanel);
    var btn = document.createElement('button');
    btn.id = BTN_ID;
    btn.textContent = 'Analytics';
    btn.style.cssText = 'position:fixed;bottom:20px;right:20px;padding:8px 16px;background:#4a90d9;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:500;cursor:pointer;z-index:9998;box-shadow:0 2px 10px rgba(74,144,217,0.3);';
    btn.addEventListener('click', togglePanel);
    document.body.appendChild(btn);
  }

  function togglePanel() {
    var panel = document.getElementById(PANEL_ID);
    if (!panel) return;
    isPanelVisible = !isPanelVisible;
    panel.style.display = isPanelVisible ? 'block' : 'none';
    if (isPanelVisible) renderPanel();
  }

  function destroyUI() {
    var panel = document.getElementById(PANEL_ID);
    if (panel) panel.parentNode.removeChild(panel);
    var btn = document.getElementById(BTN_ID);
    if (btn) btn.parentNode.removeChild(btn);
    isPanelVisible = false;
  }

  CardSpoke_MODS.register({
    name: 'Analytics Dashboard',
    hooks: {
      onAppInit: function() {
        createUI();
        recalculateStats([]);
        renderPanel();
        console.log('[Analytics] Dashboard initialized');
      },
      onCardSave: function(cardData) {
        if (cardData) {
          stats.totalCards++;
          stats.totalWords += countWords(cardData.body);
          stats.averageWordsPerCard = stats.totalCards > 0 ? Math.round(stats.totalWords / stats.totalCards) : 0;
          var today = getToday();
          stats.dailyActivity[today] = (stats.dailyActivity[today] || 0) + 1;
          stats.cardsCreatedToday = stats.dailyActivity[today];
          if (cardData.tags) {
            for (var i = 0; i < cardData.tags.length; i++) {
              stats.tagCounts[cardData.tags[i]] = (stats.tagCounts[cardData.tags[i]] || 0) + 1;
            }
            var sorted = Object.keys(stats.tagCounts).sort(function(a, b) {
              return stats.tagCounts[b] - stats.tagCounts[a];
            });
            stats.mostUsedTags = sorted.slice(0, 5);
          }
          stats.lastUpdated = new Date().toLocaleTimeString();
          if (isPanelVisible) renderPanel();
        }
        return cardData;
      },
      onDisable: function() {
        destroyUI();
        console.log('[Analytics] Dashboard disabled');
      }
    }
  });
})()

css:
.cs-analytics-panel {
  font-family: system-ui, -apple-system, sans-serif;
}

.cs-analytics-panel .stat-card {
  background: var(--bg-card, #ffffff);
  border: 1px solid var(--accent-border, #e0e0e0);
  border-radius: 8px;
  padding: 12px;
  text-align: center;
}

.cs-analytics-panel .stat-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-primary, #333333);
}

.cs-analytics-panel .stat-label {
  font-size: 11px;
  color: var(--text-secondary, #888888);
  margin-top: 4px;
}

.cs-analytics-panel .tag-bar {
  height: 4px;
  background: var(--bg-hover, #f0f0f0);
  border-radius: 2px;
  overflow: hidden;
}

.cs-analytics-panel .tag-bar-fill {
  height: 100%;
  background: var(--accent-primary, #4a90d9);
  border-radius: 2px;
  transition: width 0.3s ease;
}
